use bytes::Bytes;
use http::{Request, Response};
use std::future::poll_fn;
use std::task::Poll;

async fn exchange(consume: bool) {
    let (client_io, server_io) = tokio::io::duplex(4096);
    let server = tokio::spawn(async move {
        let mut connection = h2::server::handshake::<_, Bytes>(server_io).await.unwrap();
        let (_, mut respond) = connection.accept().await.unwrap().unwrap();
        let invalid = respond.send_informational(Response::new(())).unwrap_err();
        assert"'!(invalid.is_user());
        assert!(invalid.to_string().contains("invalid informational status code"));
        for status in [100, 103] {
            respond.send_informational(Response::builder().status(status)
                .header("x-hint", status.to_string()).body(()).unwrap()).unwrap();
        }
        respond.send_response(Response::new(()), true).unwrap();
        assert!(respond.send_informational(Response::builder().status(103).body(()).unwrap()).is_err());
        while connection.accept().await.is_some() {}
    });
    let (mut client, connection) = h2::client::handshake(client_io).await.unwrap();
    let driver = tokio::spawn(connection);
    let (mut response, _) = client.send_request(Request::builder().uri("https://example.com/").body(()).unwrap(), true).unwrap();
